('fisher-bsba', 'degree', 'Bachelor of Science in Business Administration (BSBA)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', 121, 2.0, 'Minimum 121 credit hours and a 2.0 cumulative GPA in the specialization. General Education totals 32-39 credit hours; business foundation courses also count toward GE Writing, Math & Quantitative Reasoning, and Social & Behavioral Sciences. Requirements change for students who begin in Autumn 2027 or later.', 'https://fisher.osu.edu/undergraduate/academics/curriculum-requirements', 0, '{}'::text[], null, 'autumn-2022', 'spring-2027', null, '{}'::text[], '{}'::jsonb),
('spec-accounting', 'specialization', 'Accounting', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/accounting', 1, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-aviation-management', 'specialization', 'Aviation Management', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'Offered with the Center for Aviation Studies. Students in this track can''t enroll in the Professional Pilot Certification.', 'https://fisher.osu.edu/undergraduate/academics/specializations/aviation-management', 2, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-business-management', 'specialization', 'Business Management (regional campuses)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'Offered on regional campuses. Columbus students follow the prerequisites on each course''s own specialization sheet.', 'https://fisher.osu.edu/undergraduate/academics/specializations/business-management', 3, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-economics', 'specialization', 'Economics', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'Economics students must earn a C- or higher in ECON 2001 and ECON 2002.', 'https://fisher.osu.edu/undergraduate/academics/specializations/economics', 4, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-finance', 'specialization', 'Finance', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/finance', 5, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-human-resources', 'specialization', 'Human Resources', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/human-resources', 6, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-information-systems', 'specialization', 'Information Systems', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/information-systems', 7, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-international-business', 'specialization', 'International Business', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/international-business', 8, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-logistics-management', 'specialization', 'Logistics Management', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/logistics-management', 9, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-marketing', 'specialization', 'Marketing', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/marketing', 10, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-operations-management', 'specialization', 'Operations Management (Operations track)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/operations-management', 11, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-operations-purchasing', 'specialization', 'Operations Management (Purchasing track)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/operations-management', 12, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-tech-innovation', 'specialization', 'Tech Innovation', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'New in Autumn 2026 (approved by the Council on Academic Affairs, Feb 2026). Requires an application in year 1 (minimum 3.0 GPA) and starts in year 2 with a one-semester immersion, then one Builders Studio course each semester junior and senior year with corporate-sponsored projects. Takes at least 5 semesters.', 'https://oaa.osu.edu/sites/default/files/documents/FCOB%20-%20Proposal%20to%20establish%20a%20Tech%20Innovation%20Specialization%20in%20the%20Business%20Administration%20major.pdf', 13, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('spec-real-estate', 'specialization', 'Real Estate', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/real-estate', 14, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('fisher-bsba-gel', 'degree', 'Bachelor of Science in Business Administration (BSBA)', 'Fisher College of Business', 'Fisher BSBA, entered before Autumn 2022 (GE Legacy)', 121, 2.0, 'Minimum 121 credit hours and a 2.0 cumulative GPA in the specialization. General Education totals 32-39 credit hours; business foundation courses also count toward GE Writing, Math & Quantitative Reasoning, and Social & Behavioral Sciences. Requirements change for students who begin in Autumn 2027 or later. Students who entered before Autumn 2022 follow the GE Legacy instead of the current GE.', 'https://fisher.osu.edu/undergraduate/academics/curriculum-requirements', 15, '{}'::text[], null, null, 'summer-2022', 'fisher-bsba', '{}'::text[], '{}'::jsonb),
('sp-accounting-honors', 'special', 'Accounting Honors Program', 'Fisher College of Business', 'Accounting Honors, Class of 2028 and later (entered Autumn 2024 or later)', null, 3.5, 'Cohort program of about 30 students a year; apply in the spring of your first year (first-year autumn GPA of 3.5+). MATH 1131 is the minimum (1151 or 1161 recommended), and MATH 1151-2 or 1161-2 plus ECON 2001H and 2002H strengthen an application. Extra economics or math, or a minor or second major in Economics or Statistics, is encouraged. The program doesn''t allow winter internships; most students intern in the summer after junior year. Students in the combined BSBA/MAcc program may replace senior-year honors courses with MAcc classes (see Professor Patrick Kielty). Source: Accounting Honors program structure for 2025-26 sophomores (Class of 2028 and later).', 'https://fisher.osu.edu/undergraduate/academics/honors/accounting', 16, '{}'::text[], 'fisher-bsba', 'autumn-2024', null, null, array['spec-accounting']::text[], '{"substitute": [{"code": "ACCTMIS 4200", "with": ["ACCTMIS 5200H"], "note": "Honors Advanced Accounting replaces Advanced Financial Accounting"}, {"code": "ACCTMIS 4500", "with": ["ACCTMIS 5500H"], "note": "Honors Auditing replaces Auditing Principles & Procedures"}], "waive": [{"code": "BUSMHR 2292", "note": "Waived for students who complete the Accounting Honors program"}, {"code": "BUSOBA 2321", "when_taken": "ACCTMIS 3100H", "note": "Waived once you complete ACCTMIS 3100H"}]}'::jsonb),
('sp-accounting-honors-2027', 'special', 'Accounting Honors Program', 'Fisher College of Business', 'Accounting Honors, Class of 2027 and earlier (entered before Autumn 2024)', null, 3.5, 'From Fisher''s Graduation with Honors in Accounting page (requirements sheet for Spring 2027 graduates). Accelerated BSBA/MAcc students may substitute specific MAcc courses for ACCTMIS 5200H and 5500H. Course waivers for earlier classes aren''t published; confirm them with the program director.', 'https://fisher.osu.edu/undergraduate/academics/honors/accounting/graduation-requirements', 17, '{}'::text[], 'fisher-bsba', null, 'summer-2024', 'sp-accounting-honors', array['spec-accounting']::text[], '{"substitute": [{"code": "ACCTMIS 4200", "with": ["ACCTMIS 5200H"], "note": "Honors Advanced Accounting replaces Advanced Financial Accounting"}, {"code": "ACCTMIS 4500", "with": ["ACCTMIS 5500H"], "note": "Honors Auditing replaces Auditing Principles & Procedures"}]}'::jsonb),
('sp-finance-honors', 'special', 'Finance Honors Program', 'Fisher College of Business', 'Finance Honors (requirements sheet for Spring 2027 graduates)', null, 3.5, 'Apply in the spring of sophomore year with a 3.5 GPA; BUSFIN 3220 needs an A- (it can be taken that spring for conditional admission). Also finish ACCTMIS 2200/2300, BUSMHR 2292, and BUSOBA 2320 by then. Contact FCOB-honors@osu.edu with questions.', 'https://fisher.osu.edu/undergraduate/academics/honors/finance', 18, '{}'::text[], 'fisher-bsba', null, null, null, array['spec-finance']::text[], '{"substitute": [{"code": "BUSFIN 4201", "with": ["BUSFIN 4202H"], "note": "Honors Financial Data replaces BUSFIN 4201"}]}'::jsonb),
('sp-honors-leadership', 'special', 'Honors Leadership Program', 'Fisher College of Business', 'Fisher Honors Leadership (current)', null, 3.5, 'For any business specialization. Apply in January of sophomore year with a 3.5 GPA, after finishing ACCTMIS 2200, ACCTMIS 2300, BUSOBA 2320, and BUSMHR 2292 (honors versions recommended). No program classes in the spring of junior year. Graduating with Honors in Business Administration also needs a minor, major, or concentration outside business and an approved Leadership Challenge.', 'https://fisher.osu.edu/undergraduate/academics/honors/honors-leadership', 19, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('sp-honors-cohort', 'special', 'Honors Cohort Program', 'Fisher College of Business', 'Fisher Honors Cohort (current)', null, 3.5, '40 juniors and 40 seniors from any business specialization, chosen in a selective process in the spring of sophomore year. Includes a two-day onboarding, business trips (Chicago, Seattle/San Francisco, NYC Summit), a negotiation challenge, a service project, and a senior-year international trip. Fisher''s page names the core subjects but not course numbers; the honors sections below are BuckAI''s match from Class Search. Confirm with the Honors Cohort graduation requirements sheet.', 'https://fisher.osu.edu/undergraduate/academics/honors/honors-cohort', 20, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('sp-ibe-core', 'special', 'Integrated Business & Engineering (IBE) Honors: Core track', 'Fisher College of Business', 'IBE Honors graduation requirements (current)', null, 3.5, 'Four-year program with a separate application after admission to Fisher, before the first year. BSBA students on the Core track complete an Engineering Sciences minor. All other BSBA requirements still apply, except GENED 4001, which is built into the capstone.', 'https://fisher.osu.edu/undergraduate/academics/honors/ibe/graduation-requirements', 21, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{"waive": [{"code": "GENED 4001", "note": "Built into the IBE capstone"}]}'::jsonb),
('sp-ibe-si', 'special', 'Integrated Business & Engineering (IBE) Honors: Software Innovation track', 'Fisher College of Business', 'IBE Honors graduation requirements (current)', null, 3.5, 'BSBA students on the Software Innovation track complete a Computer Science minor. All other BSBA requirements still apply, except GENED 4001, which is built into the capstone.', 'https://fisher.osu.edu/undergraduate/academics/honors/ibe/graduation-requirements', 22, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{"waive": [{"code": "GENED 4001", "note": "Built into the IBE capstone"}]}'::jsonb),
('sp-research-distinction', 'special', 'Honors Research Distinction', 'Fisher College of Business', 'Fisher Honors Research Distinction (current)', null, 3.5, 'Apply by August 1 before senior year with a confirmed faculty advisor and a 1-2 page proposal. To start, you need a 3.5 GPA and 12 hours of honors coursework (graded research in Fisher) or 18 hours (S/U research outside Fisher). Research runs the full academic year, so plan to graduate in spring or summer.', 'https://fisher.osu.edu/undergraduate/academics/honors/research-distinction', 23, '{}'::text[], 'fisher-bsba', null, null, null, '{}'::text[], '{}'::jsonb),
('sp-bsba-macc', 'special', 'Accelerated BSBA/Master of Accounting (MAcc)', 'Fisher College of Business', 'Fisher Accelerated MAcc (current)', null, 3.5, 'For Fisher Accounting students with a 3.5 GPA. Apply early in your junior year (talk to an advisor by the end of sophomore year). You can leave with just the BSBA after the first MAcc semester once every BSBA course (or its MAcc substitute) is done.', 'https://fisher.osu.edu/graduate/macc/academics/bsbamacc-program', 24, '{}'::text[], 'fisher-bsba', null, null, null, array['spec-accounting']::text[], '{}'::jsonb),
('sp-university-honors', 'special', 'University Honors (Honors & Scholars)', 'Fisher College of Business', 'Ohio State Honors Program (current)', null, 3.5, 'Admitted through the Common Application, or later with a 3.75 GPA and 12 graded hours. University Honors alone doesn''t give a Fisher honors designation; finish a Fisher honors program or Honors Research Distinction for that.', 'https://honors-scholars.osu.edu/honors/programs', 25, '{}'::text[], null, null, null, null, '{}'::text[], '{}'::jsonb)
